from pathlib import Path
import json
p=Path(__file__).parent/'prompt-catalog.json';c=json.loads(p.read_text(encoding='utf-8'))
base='全新制作一张独立游戏技能关键透明纹理母图，只画一个主体，不画武器装备展示，不画人物、角色、病毒、完整细胞、器官、房屋、平台或UI。沿用现有清新2D手绘生物幻想、奶白有机陶瓷与温润凝胶、哑光宽色块和轻细轮廓，技能能量可比普通物品明亮但不能写实硬科幻或霓虹雾团。所有结构集中完整居中，正方1024源图最长轴75%，四周安全留白，主体不裁边。纹理会在运行时被旋转缩放，不能烘入任何范围指示圈、地面椭圆、落点圆环、背景、文字、数字、符号、品质边框、水印。均匀纯白#FFFFFF底，全部非主体区域和结构孔洞也纯白，方便后期真实alpha去底；不画灰影、纸纹底、渐变背景、棋盘格、大面积白色雾晕。能量用有色且轮廓清楚的宽刷痕，不用向背景泛白的光晕。'
items={
'fx.steady-ultimate':('蜂后歼灭阵','af919e1e-ec11-43eb-b686-b28c8442cd2b','一个薄荷青色蜂后枪阵的独立蜂巢射口，七个短粗奶白蛋白喷口围成紧凑六瓣蜂巢簇，正中央一枚略大的喷口，每个孔有深青内壁和薄荷凝胶唇边。透视稍俯视，发射口朝画面右上方但整件不带握柄枪身，只保留集中喷口模块。外轮廓高低起伏，不是平面的六边形图标，不是范围圈，不是蜜蜂、巢房建筑。可有几根极短青色蜂针正在口内蓄势，但不发散长拖尾。'),
'fx.piercing-ultimate':('贯脉天轮','0d1be017-1770-452f-a969-8f689b00f9ad','一枚巨型琥珀回旋刃天轮，三片宽大、温润象牙刀脊与琥珀橙刃面绕小型暖金蛋白轴心旋接，形成开放镂空的旋转轮刃。三片大月牙实际相连，是有体积的物理武器刃轮，不是地图范围圈/魔法阵/光环。正上方轻斜俯视、圆润锋面，刃端清楚，琥珀与奶金高光克制。没有飞散碎片、人物、弓身或握把，不画完整圆形外边框。'),
'fx.thunder-ultimate':('天穹裁决',None,'一束竖向青紫金裁决雷柱：中间一枚饱满的青紫雷核，外围三道粗细不同、连续有折角的青蓝与灰紫雷弧从上向下汇聚，雷核中心少量暖金高亮，底端收成一个清楚的短尖。轮廓高而窄，最宽处约高度的45%，像有机能量束而不是枪、塔楼、石柱或UI闪电符号。只画雷柱与雷核，不画落地爆圈、地面阴影、粒子云、范围环或角色。宽色雷纹边界清楚，光在有色实体之内，背景保持干净纯白。'),
'fx.redblade-ultimate':('赤曜无生域',None,'一条宽大有力的红金斩疫刀弧，开放C形的珊瑚红厚刷刃面、暖金锋缘，弧线两端明显收尖但保持圆润手绘，内缘有一层奶白蛋白流光。单条独立刀弧，开口朝右，弧线覆盖约四分之三圈但绝不闭合，不是技能范围圈、圆盘、魔法阵或UI外框。以红金能量刃面和宽色块表达无生剑域的关键一次斩击，不画完整武器、手柄、人物、血、火焰墙或地面。')}
for key,(title,node,detail) in items.items():
 c['sources'][key]={'title':title,'resolution':'1K','prompt':base+detail}
 if node:c['sources'][key]['follow_up_node']=[node]
p.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
